127:     location ^~ /api/tts/assets/voice-library/ {
128:         alias /opt/castreader/shared/tts-catalog/voice-library/;
129:         add_header Cache-Control "public, max-age=604800, immutable" always;
130:         add_header X-CastReader-TTS-Route cn-static always;
131:     }
132: 
133:     # 未列入中国区合同的 TTS 路径 fail closed，禁止意外落到应用层再回源。
134:     location ^~ /api/tts/ {
135:         return 404;
136:     }
137: 
138:     # 旧 Markdown TTS 会把生成音频写入境外 R2。中国入口在完成 COS
139:     # 缓存迁移前 fail closed，避免绕开上面的境内 TTS 与静态资源合同。
140:     location ^~ /api/markdown-tts/ {
141:         return 404;
142:     }
143: 
144:     # 文档、STS 与上传协议保持原路径，避免客户端维护第二套 API 合同。
145:     location = /documents {
146:         proxy_pass https://api.castreader.ai;
147:         proxy_http_version 1.1;
148:         proxy_ssl_server_name on;
149:         proxy_ssl_name api.castreader.ai;
150:         proxy_set_header Host api.castreader.ai;
151:         proxy_set_header X-Forwarded-For $remote_addr;
152:         proxy_set_header X-Real-IP $remote_addr;
153:         proxy_set_header X-Forwarded-Proto https;
154:         proxy_read_timeout 120s;
155:     }
156: 
157:     location = /sts {
158:         proxy_pass https://api.castreader.ai;
159:         proxy_http_version 1.1;
160:         proxy_ssl_server_name on;
161:         proxy_ssl_name api.castreader.ai;
162:         proxy_set_header Host api.castreader.ai;
163:         proxy_set_header X-Forwarded-For $remote_addr;
164:         proxy_set_header X-Real-IP $remote_addr;
165:         proxy_set_header X-Forwarded-Proto https;
166:         proxy_read_timeout 120s;
167:     }
168: 
169:     location = /async-md-upload-by-url {
170:         client_max_body_size 10m;
171:         proxy_pass https://api.castreader.ai;
172:         proxy_http_version 1.1;
173:         proxy_ssl_server_name on;
174:         proxy_ssl_name api.castreader.ai;
175:         proxy_set_header Host api.castreader.ai;
176:         proxy_set_header X-Forwarded-For $remote_addr;
177:         proxy_set_header X-Real-IP $remote_addr;
178:         proxy_set_header X-Forwarded-Proto https;
179:         proxy_read_timeout 600s;
180:         proxy_send_timeout 600s;
181:     }
182: 
183:     location = /upload {
184:         client_max_body_size 100m;
185:         proxy_pass https://api.castreader.ai;
186:         proxy_http_version 1.1;
187:         proxy_ssl_server_name on;
188:         proxy_ssl_name api.castreader.ai;
189:         proxy_set_header Host api.castreader.ai;
190:         proxy_set_header X-Forwarded-For $remote_addr;
191:         proxy_set_header X-Real-IP $remote_addr;
192:         proxy_set_header X-Forwarded-Proto https;
193:         proxy_request_buffering off;
194:         proxy_read_timeout 900s;
195:         proxy_send_timeout 900s;
196:     }
